function refDaysInMonth(year, month) {
  // normalize month to 1..12 and compute resulting year
  const y = year + Math.floor((month - 1) / 12);
  const m = ((month - 1) % 12 + 12) % 12 + 1;
  const d = new Date(Date.UTC(2000, m - 1, 1));
  d.setUTCFullYear(y);
  d.setUTCMonth(m, 0); // last day of month m
  return d.getUTCDate();
}

